syntax:
type-specifier-specifier ... identifier [array-specifier] [pointer-specifier] [function-specifier] ... ;
// With nested declarations, parentheses are used to specify precedence, e.g.,
// int (*fp)(int);
// declares fp as a pointer to a function taking int and returning int.

code_example:
typedef int (*func_ptr)(double);
struct Data {
    int id;
    struct Data *next;
    func_ptr compute;
};
void example() {
    struct Data d;
    d.compute = (func_ptr) some_function;
}
